-- Development fixtures for all tables in hire_me.
-- Automatically executed after 01-schema.sql and 02-seed-roles.sql on a fresh MySQL volume.
-- Accounts: admin / Admin@123; recruiter01..03 and candidate01..08 / Demo@123.
-- Fixed UUIDs make JOIN queries reproducible. This script targets an empty database.
-- CV records are PENDING metadata only: this SQL does not upload objects to RustFS.
USE hire_me;
SET NAMES utf8mb4;
SET @seed_now = NOW();
START TRANSACTION;


SELECT CONCAT('00000030-0000-0000-0000-', LPAD(ROW_NUMBER() OVER (ORDER BY u.id), 12, '0')),
       u.id, r.id, u.created_at, u.created_by, u.last_modified_at, u.last_modified_by, FALSE
FROM `users` u
JOIN `roles` r ON r.name = CASE
  WHEN u.username = 'admin' THEN 'ADMIN'
  WHEN u.username LIKE 'recruiter%' THEN 'RECRUITER'
  ELSE 'CANDIDATE' END;








COMMIT;
